-- Campos para completar en los acuerdos de las plantillas de pactos ({horas}, {lugar}, {hora}…).
-- Solo cambia los textos originales; si una plantilla ya se editó en el admin, ese acuerdo queda igual.
UPDATE "PactTemplate" SET "clauses" = (replace(replace(replace(replace(replace(replace(replace(replace(replace("clauses"::text, 'máximo ___ horas, después', 'máximo {horas} horas, después'), 'cargando en ___ desde las ___.', 'cargando en {lugar} desde las {hora}.'), 'máximo ___ minutos por día.', 'máximo {minutos} minutos por día.'), 'Juego máximo ___ minutos y aviso', 'Juego máximo {minutos} minutos y aviso'), 'Máximo ___ minutos al día y nada', 'Máximo {minutos} minutos al día y nada'), 'TikTok máximo ___ minutos al día', 'TikTok máximo {minutos} minutos al día'), 'Instagram máximo ___ minutos al día.', 'Instagram máximo {minutos} minutos al día.'), 'Después de las ___ silencio', 'Después de las {hora} silencio'), 'máximo ___ partidas o ___ minutos al día', 'máximo {partidas} partidas o {minutos} minutos al día'))::jsonb WHERE "clauses"::text LIKE '%\_\_\_%';
